# lc_parser.py - a simple lambda calculus parser

import re

def tokenize_lc(source):
    """Tokenize a lambda calculus expression."""
    pattern = r'λ|\\|->|[a-zA-Z_][a-zA-Z0-9_]*|[().]|\s+'
    tokens = []
    for tok in re.findall(pattern, source):
        if not tok.strip():
            continue
        tokens.append(tok)
    return tokens

def parse_lc(source):
    """Parse a lambda calculus expression into an AST."""
    tokens = tokenize_lc(source)
    pos = [0]

    def peek():
        return tokens[pos[0]] if pos[0] < len(tokens) else None

    def consume(expected=None):
        tok = tokens[pos[0]]
        if expected and tok != expected:
            raise SyntaxError(f"Expected {expected!r}, got {tok!r}")
        pos[0] += 1
        return tok

    def parse_expr():
        """expr ::= lam | app"""
        if peek() in ('λ', '\\'):
            return parse_lam()
        return parse_app()

    def parse_lam():
        consume()   # consume λ or \
        param = consume()
        if peek() == '.':
            consume('.')
        elif peek() == '->':
            consume('->')
        body = parse_expr()
        return lam(param, body)

    def parse_app():
        """Left-associative application."""
        func = parse_atom()
        while peek() and peek() not in (')', '.'):
            # Don't consume a λ as an argument without parens
            if peek() in ('λ', '\\'):
                break
            arg = parse_atom()
            func = app(func, arg)
        return func

    def parse_atom():
        tok = peek()
        if tok == '(':
            consume('(')
            e = parse_expr()
            consume(')')
            return e
        if tok and tok not in ('λ', '\\', ')', '.', '->'):
            consume()
            return var(tok)
        raise SyntaxError(f"Unexpected token: {tok!r}")

    return parse_expr()

# Test
print(parse_lc("λx. x"))
